/* ---------- المكوّن ---------- */
let _lastPick = -1;
export default function ThinkingWhale({ t, label = "المستشار يفكّر…" }) {
  const host = useRef(null);
  useEffect(() => {
    const node = host.current;
    if (!node) return;
    let i = Math.floor(Math.random() * ANIMS.length);
    if (ANIMS.length > 1 && i === _lastPick) i = (i + 1 + Math.floor(Math.random() * (ANIMS.length - 1))) % ANIMS.length;
    _lastPick = i;
    const spec = ANIMS[i];
    node.textContent = "";
    const w = createWhale(node, { viewBox: spec.vb });
    w.svg.style.cssText = "display:block;width:100%;height:100%";
    const A = makeAPI(w, spec.D);
    spec.build(A, w);
    const reduce = typeof window !== "undefined" && window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) w.anims.forEach((a) => { a.pause(); a.currentTime = spec.D * 0.42; });
    return () => { try { w.anims.forEach((a) => a.cancel()); } catch (e) {} node.textContent = ""; };
  }, []);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
      <div ref={host} role="img" aria-label="الحوت يتحرك أثناء التفكير" style={{ flexShrink: 0, width: 150, aspectRatio: "4 / 3", borderRadius: 16, overflow: "hidden", background: "linear-gradient(180deg,#14233f,#1c3763)" }} />
      <div style={{ fontSize: 12.5, color: t ? t.L3 : "#888" }}>{label}</div>
    </div>
  );
}
